#include <stdint.h>
#include <string.h>
#include <sys/time.h>

#define WILDCARD_THRESHOLD 10
#define WILDCARD_WINDOW_US 10000000ULL /* 10 s */
#define WILDCARD_SLOTS     1024        /* power of 2 */
#define WILDCARD_PROBES    8

typedef struct {
    uint32_t src, dst;
    uint64_t last_us;                  /* 0: free slot */
    uint32_t head, count;              /* ring of the last THRESHOLD - 1 query times */
    uint64_t t[WILDCARD_THRESHOLD - 1];
} wildcard_peer_t;

static wildcard_peer_t wildcard_peers[WILDCARD_SLOTS];

static wildcard_peer_t *wildcard_lookup(uint32_t src, uint32_t dst) {
    uint32_t h = (src * 2654435761u) ^ (dst * 2246822519u), i;
    wildcard_peer_t *victim = NULL, *p;
    for (i = 0; i < WILDCARD_PROBES; i++) {
        p = &wildcard_peers[(h + i) & (WILDCARD_SLOTS - 1)];
        if (p->last_us != 0 && p->src == src && p->dst == dst)
            return p;
        if (victim == NULL || p->last_us < victim->last_us)
            victim = p;
    }
    memset(victim, 0, sizeof(*victim));
    victim->src = src;
    victim->dst = dst;
    return victim;
}

static int em_check_wildcard_enum(const void *ip_src, const void *ip_dst, const void *utime, const char *val) {
    struct timeval tv;
    uint32_t src, dst;
    uint64_t now;
    wildcard_peer_t *p;
    int alert;

    if (ip_src == NULL || ip_dst == NULL || utime == NULL || val == NULL)
        return 0;
    if (strchr(val, '*') == NULL && strchr(val, '?') == NULL)
        return 0;

    memcpy(&src, ip_src, sizeof(src));
    memcpy(&dst, ip_dst, sizeof(dst));
    memcpy(&tv, utime, sizeof(tv)); /* meta.utime is a struct timeval */
    now = (uint64_t)tv.tv_sec * 1000000ULL + (uint64_t)tv.tv_usec;
    if (now == 0)
        now = 1;

    p = wildcard_lookup(src, dst);
    /* when the ring is full, t[head] is the oldest of the previous THRESHOLD - 1 queries */
    alert = (p->count == WILDCARD_THRESHOLD - 1 && now >= p->t[p->head]
             && now - p->t[p->head] <= WILDCARD_WINDOW_US);
    p->t[p->head] = now;
    p->head = (p->head + 1) % (WILDCARD_THRESHOLD - 1);
    if (p->count < WILDCARD_THRESHOLD - 1)
        p->count++;
    p->last_us = now;
    return alert;
}
